100	{
101	    /*Save the info because an lv_async_call_cancel might delete it in the callback*/
102	    lv_async_info_t * info = (lv_async_info_t *)timer->user_data;
103	    lv_async_info_t info_save = *info;
104	    lv_timer_delete(timer);
105	    lv_free(info);
106	
107	    info_save.cb(info_save.user_data);
