174	        counter.count += 1;
175	        return r.replacement;
176	      });
177	    }
178	    return out;
179	  }
180	  if (Array.isArray(value)) {
181	    return value.map((v) => redactValue(v, rules, counter));
182	  }
183	  if (value && typeof value === "object") {
184	    const out = {};
185	    for (const [k, v] of Object.entries(value)) {
186	      out[k] = redactValue(v, rules, counter);
187	    }
188	    return out;
189	  }
190	  return value;
191	}
