309	
310	    if (SKIP_PART_TYPES.has(type)) continue;
311	
312	    if (type === "text" && part.text) {
313	      out.push({
314	        role,
315	        ts: baseTsIso,
316	        text: part.text,
317	        ...(modelStr ? { model: modelStr } : {}),
318	        ...(typeof msg.tokens_in === "number" ? { tokens_in: msg.tokens_in } : {}),
319	        ...(typeof msg.tokens_out === "number" ? { tokens_out: msg.tokens_out } : {}),
320	      });
321	    } else if (type === "reasoning" || type === "thinking") {
322	      out.push({
323	        role,
324	        ts: baseTsIso,
325	        thinking: part.text || part.content || "",
326	        ...(modelStr ? { model: modelStr } : {}),
327	      });
328	    } else if (type === "tool" || type === "tool-invocation") {
329	      const toolName = part.toolName || part.tool || part.name || "unknown";
330	      const callId = part.callID || part.callId || part.tool_call_id || `call_${out.length}`;
331	      const input = part.args || part.state?.input || part.input || null;
332	      const output = part.result || part.state?.output || part.output || null;
333	      out.push({
334	        role: "tool",
335	        ts: baseTsIso,
336	        tool_name: toolName,
337	        tool_call_id: callId,
338	        input,
339	        output,
340	        ...(part.metadata ? { metadata: part.metadata } : {}),
341	      });
