// Probe a deskmate broker the way the device does: subscribe, send hello,
// wait for hello_ack. Exit 0 = bridge alive, 2 = no answer, 1 = connect error.
import mqtt from "mqtt";

const url = process.env.BROKER || "mqtt://10.189.140.244:1883";
const base = `${process.env.TOPIC_PREFIX || "deskmate"}/${process.env.DEVICE_ID || "goldfish-1"}`;
const nonce = `probe${Date.now()}`;

const c = mqtt.connect(url, {
  username: process.env.DESKMATE_MQTT_USERNAME,
  password: process.env.DESKMATE_MQTT_PASSWORD,
  clientId: `probe-${nonce}`,
  connectTimeout: 5000,
});

let answered = false;
c.on("connect", () => {
  c.subscribe(`${base}/#`, (err) => {
    if (err) { console.log("subscribe error:", err.message); process.exit(1); }
    console.log(`connected to ${url}, subscribed ${base}/#, sending hello`);
    c.publish(`${base}/device-to-bridge`, `${JSON.stringify({ v: 1, cmd: "hello", connection_nonce: nonce })}\n`);
  });
});
c.on("message", (topic, payload) => {
  const text = payload.toString().slice(0, 300);
  console.log("MSG", topic, text);
  if (topic.endsWith("/bridge-to-device") && text.includes("hello_ack")) {
    answered = true;
    console.log(">>> BRIDGE ALIVE (hello_ack received)");
    c.end(true);
    process.exit(0);
